function t(key, replacements = null) {
    const lang = localStorage.getItem('admin_lang') || localStorage.getItem('lang') || 'ar';
    let val = key;
    if (i18n[lang] && i18n[lang][key] !== undefined) {
        val = i18n[lang][key];
    } else if (typeof tr === 'function') {
        val = tr(key);
    }
    if (replacements && typeof replacements === 'object') {
        for (let k in replacements) {
            val = val.replace(`{${k}}`, replacements[k]);
        }
    }
    return val;
}
window.t = t;

function translateStaticDOM() {
    const elements = document.querySelectorAll('[data-i18n]');
    elements.forEach(el => {
        const key = el.getAttribute('data-i18n');
        const translated = t(key);
        if (translated !== key) {
            el.textContent = translated;
        }
    });

    const elementsTitle = document.querySelectorAll('[data-i18n-title]');
    elementsTitle.forEach(el => {
        const key = el.getAttribute('data-i18n-title');
        const translated = t(key);
        if (translated !== key) {
            el.setAttribute('title', translated);
        }
    });

    const elementsPlaceholder = document.querySelectorAll('[data-i18n-placeholder]');
    elementsPlaceholder.forEach(el => {
        const key = el.getAttribute('data-i18n-placeholder');
        const translated = t(key);
        if (translated !== key) {
            el.setAttribute('placeholder', translated);
        }
    });
}

function applyLanguage() {
    if (currentLang === 'en') {
        document.body.classList.add('lang-en');
        document.body.style.direction = 'ltr';
    } else {
        document.body.classList.remove('lang-en');
        document.body.style.direction = 'rtl';
    }
}

// Ensure language applies on load
document.addEventListener("DOMContentLoaded", () => {
    translateStaticDOM();
    applyLanguage();
});
